package com.dy.artisan3d.data.modelimport com.dy.artisan3d.domain.model.Brandimport kotlinx.serialization.Serializable@Serializabledata class BrandResponse(    val data: List<BrandDto>)@Serializabledata class BrandDto(    val id: Int,    val image: String?,    val products_count: Int,    val translations: Map<String, BrandTranslationDto>)@Serializabledata class BrandTranslationDto(    val name: String,    val address: String)fun BrandDto.toUIModel(currentLang: String): Brand {    val translation = translations[currentLang] ?: translations["en"]    return Brand(        id = id,        image = image,        productsCount = products_count,        name = translation?.name ?: "No name",        address = translation?.address ?: ""    )}